import React from 'react';
import {bipolPerc} from '../lib/transform'
import ScaleSliderSVG from './ScaleSliderSVG'
import { Observable, fromEvent, race } from 'rxjs';
import { sampleTime, takeUntil, take, tap, map, filter } from 'rxjs/operators';

/*
TODO: handle touchcancel and mouseout
*/

class GestureableSVG extends Component{
  constructor(props) {
    super(props);
  }
  handleMove = ({currX, currY, startVal, startX, startY}) => {
    let delta = 2.0 * (currX-startX) / this.props.width
    // console.debug('move', {
    //   currX, currY, startVal, startX, startY, delta
    // })
    this.props.onChange(
      Math.max(-1, Math.min(1, startVal + delta)));
  }
  handleMouseDown = (e) => {
    let startX = e.clientX;
    let startY = e.clientY;
    let startVal = this.props.value || 0.0;
    // console.debug('mousedown', e, this);

    let mouseMoveObs = fromEvent(
      document, 'mousemove'
    ).pipe(
      takeUntil(
        fromEvent(document, 'mouseup').pipe(take(1))
      ),
      sampleTime(UI_PERIOD_MS)
    ).subscribe((e)=>{
      // console.debug('mousemove', e, this);
      e.stopPropagation()
      e.preventDefault()
      this.handleMove({
        currX: e.clientX,
        currY: e.clientY,
        startVal: startVal,
        startX: startX,
        startY: startY
      })
    });
  }
  handleTouchStart = (e) => {
    // console.debug('touched', e.targetTouches[0]);
    // subtlety: there can be MANY touchstarts per thingy
    let touch = e.targetTouches[0];
    let touchId = touch.identifier;
    let startX = touch.clientX;
    let startY = touch.clientY;
    let startVal = this.props.value || 0.0;

    let thisTouchOnly = (e) => {
      for (let touch of e.changedTouches) {
        // console.debug('t0', touch)
        if (touch.identifier === touchId) {
          // console.debug('t1', touch)
          e.myTouch = touch
          return e
        }
      }
    }
    let existing = (e) => e !== undefined;

    let touchupObs = race(
      fromEvent(
        document, 'touchup').pipe(map(thisTouchOnly), filter(existing)),
      fromEvent(
        document, 'touchcancel').pipe(map(thisTouchOnly), filter(existing)),
    ).pipe(take(1));

    let touchMoveObs = fromEvent(
      document, 'touchmove'
    ).pipe(
      map(thisTouchOnly),
      filter(existing),
      takeUntil(touchupObs),
      sampleTime(UI_PERIOD_MS)
    ).subscribe((e)=>{
      // console.debug('touchmove', e, this);
      e.stopPropagation()
      e.preventDefault()
      this.handleMove({
        currX: e.myTouch.clientX,
        currY: e.myTouch.clientY,
        startVal: startVal,
        startX: startX,
        startY: startY
      })
    });

  }

  componentWillUnmount = () => {
    // Am not sure how to handle cleanup any more.
    // Maybe RxJs does this automatically?
    // document.removeEventListener('mouseup', this.handleMouseUp, false);
    // document.removeEventListener('touchend', this.handleTouchStart, false);
  }
  handleDoubleClick = (e) => {
    this.props.onDoubleClick();
  }
  render = () => {
    let {
      value=0,
      onDoubleClick,
      onChange,
      transform='',
    } = this.props;

    let c = (<g
      transform={transform}
      onMouseDown={this.handleMouseDown}
      onDoubleClick={this.handleDoubleClick}
      onTouchStart={this.handleTouchStart}
    >
      {this.props.children}
      </g>)
    return c
  };
}


export default GestureableSVG;
